return [{
  json: {
    META_GRAPH_API_VERSION: 'v20.0',
    META_WHATSAPP_PHONE_NUMBER_ID: '1190287117501375',
    META_WHATSAPP_ACCESS_TOKEN: 'PASTE_META_WHATSAPP_ACCESS_TOKEN_HERE',
    WHATSAPP_INVOICE_RECIPIENTS: '971568720885,9715XXXXXXXX',
    INVOICE_ALLOWED_SENDERS: 'taxinvoice@network.ae,digital.services@taqadistribution.com',
    GMAIL_INVOICE_SEARCH_QUERY: 'is:unread has:attachment (from:taxinvoice@network.ae OR from:digital.services@taqadistribution.com OR from:etisalat OR from:eand OR from:bank)'
  }
}];

const vars = $('Workflow Config').first().json;
const clean = (value) => String(value ?? '').replace(/<[^>]*>/g, ' ').replace(/&nbsp;/gi, ' ').replace(/\s+/g, ' ').trim();
const linesOf = (value) => String(value ?? '').replace(/<br\s*\/?>/gi, '\n').replace(/<\/p>/gi, '\n').replace(/<[^>]*>/g, ' ').split(/\r?\n/).map(clean).filter(Boolean);
const firstMatch = (text, patterns) => { for (const pattern of patterns) { const match = String(text || '').match(pattern); if (match) return clean(match[1] || match[0]); } return ''; };
const moneyMatch = (value) => { const match = String(value || '').replace(/,/g, '').match(/(?:AED|د\.إ)?\s*([0-9]+(?:\.[0-9]{1,2})?)\s*(?:AED|د\.إ)?/i); return match ? Number(match[1]) : null; };
const normalizePhone = (value) => { const digits = String(value || '').replace(/\D/g, ''); if (!digits) return ''; return digits.startsWith('971') ? digits : digits.replace(/^0/, '971'); };
const recipients = String(vars.WHATSAPP_INVOICE_RECIPIENTS || '').split(',').map(normalizePhone).filter(Boolean);
if (!recipients.length) throw new Error('Set WHATSAPP_INVOICE_RECIPIENTS in the Workflow Config node. Use comma-separated UAE international numbers without +.');
const allowedSenders = String(vars.INVOICE_ALLOWED_SENDERS || 'taxinvoice@network.ae,digital.services@taqadistribution.com').toLowerCase().split(',').map((item) => item.trim()).filter(Boolean);
const headerFrom = $json.headers?.from || $json.From || '';
const fromRaw = clean($json.from?.text || $json.from || $json.sender || $json.fromEmail || headerFrom || '');
const fromEmail = (fromRaw.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i)?.[0] || fromRaw).toLowerCase();
const subject = clean($json.subject || $json.Subject || $json.headers?.subject || '');
const text = [$json.text, $json.textAsHtml, $json.html, $json.textPlain, $json.snippet, subject].map((part) => String(part || '')).join('\n');
const compact = clean(text);
const isAllowedSender = !allowedSenders.length || allowedSenders.some((sender) => fromEmail.includes(sender));
const hasInvoiceKeyword = /invoice|bill|فاتورة|فاتورتك|tax invoice|bank fee|transaction fee|رسوم/i.test(compact);
if (!isAllowedSender && !hasInvoiceKeyword) return [];
let provider = 'Unknown';
let category = 'General Invoice';
if (/network\.ae|network international|\bnetwork\b/i.test(fromEmail + ' ' + compact)) { provider = 'Network International'; category = 'Bank / Network Fees'; }
else if (/taqa|taqadistribution|كهرباء|المياه|electricity|water/i.test(fromEmail + ' ' + compact)) { provider = 'TAQA Distribution'; category = 'Electricity & Water'; }
else if (/etisalat|eand|e&|اتصالات/i.test(fromEmail + ' ' + compact)) { provider = 'Etisalat / e&'; category = 'Telecom'; }
else if (/bank fee|transaction fee|card fee|merchant fee|رسوم/i.test(compact)) { provider = 'Bank Fees'; category = 'Bank Fees'; }
const lines = linesOf(text);
const accountNumber = firstMatch(compact, [/ACCOUNT NUMBER\s*([0-9]+)/i, /رقم الحساب\s*([0-9]+)/i, /Account\s*No\.?\s*([0-9]+)/i]);
const billNumber = firstMatch(compact, [/BILL NUMBER\s*([0-9]+)/i, /رقم الفاتورة\s*([0-9]+)/i, /Invoice\s*(?:No|Number)?\.?\s*([A-Z0-9-]+)/i]);
const period = firstMatch(subject + ' ' + compact, [/period\s+([0-9]{2}-[0-9]{2}-[0-9]{4}\s+to\s+[0-9]{2}-[0-9]{2}-[0-9]{4})/i, /covering the period\s+([^\.]+)/i]);
const invoiceDate = firstMatch(compact, [/YOUR TAQA Distribution BILL\s*([0-9]{1,2}\/[A-Za-z]+\/[0-9]{4})/i, /فاتورتك\s*([0-9]{1,2}\/[\u0600-\u06ff]+\/[0-9]{4})/i, /Invoice Date\s*([0-9\-\/A-Za-z\u0600-\u06ff]+)/i]);
const dueDate = firstMatch(compact, [/TOTAL TO PAY BY\s*([0-9]{1,2}\/[A-Za-z]+\/[0-9]{4})/i, /الإجمالي المستحق للدفع\s*([0-9]{1,2}\/[\u0600-\u06ff]+\/[0-9]{4})/i, /Due Date\s*([0-9\-\/A-Za-z\u0600-\u06ff]+)/i]);
let totalAmount = firstMatch(compact, [/TOTAL TO PAY(?: BY)?\s*(?:[0-9]{1,2}\/[A-Za-z]+\/[0-9]{4})?\s*AED\s*([0-9,.]+)/i, /TOTAL TO PAY INCL VAT\s*AED\s*([0-9,.]+)/i, /المبلغ المستحق شاملا ضريبة القيمة المضافة\s*([0-9,.]+)/i, /AED\s*([0-9,.]+)/i, /([0-9,.]+)\s*د\.إ/i]);
const electricityAmount = firstMatch(compact, [/Electricity\s*Commercial Tariff\s*([0-9,.]+)/i, /الكهرباء\s*تجاري\s*([0-9,.]+)/i]);
const waterAmount = firstMatch(compact, [/Water\s*Commercial Tariff\s*([0-9,.]+)/i, /المياه\s*تجاري\s*([0-9,.]+)/i]);
const property = lines.find((line) => /PLOT|SHOP|IN AND OUT|مصبغة|فرع/i.test(line)) || '';
const attachmentEntries = Object.entries($binary || {});
const pdfEntry = attachmentEntries.find(([, file]) => /pdf/i.test(file?.mimeType || '') || /\.pdf$/i.test(file?.fileName || '')) || attachmentEntries[0];
const hasAttachment = Boolean(pdfEntry);
const binaryKey = pdfEntry?.[0];
const fileName = clean(pdfEntry?.[1]?.fileName || `${provider.replace(/[^a-z0-9]+/gi, '_')}_${billNumber || Date.now()}.pdf`);
const sourceMessageId = $json.id || $json.messageId || '';
const details = [];
details.push('Provider: ' + provider);
details.push('Category: ' + category);
if (accountNumber) details.push('Account: ' + accountNumber);
if (billNumber) details.push('Bill/Invoice: ' + billNumber);
if (period) details.push('Period: ' + period);
if (invoiceDate) details.push('Invoice date: ' + invoiceDate);
if (dueDate) details.push('Due date: ' + dueDate);
if (totalAmount) details.push('Total: AED ' + totalAmount);
if (electricityAmount) details.push('Electricity: AED ' + electricityAmount);
if (waterAmount) details.push('Water: AED ' + waterAmount);
if (property) details.push('Location/branch: ' + property);
const message = ['New invoice received', ...details, 'From: ' + fromEmail, 'Subject: ' + subject, hasAttachment ? 'Attachment: PDF included' : 'Attachment: no PDF found'].join('\n');
const base = { sourceMessageId, provider, category, fromEmail, subject, accountNumber, billNumber, period, invoiceDate, dueDate, totalAmount: moneyMatch(totalAmount), totalAmountText: totalAmount, electricityAmount: moneyMatch(electricityAmount), waterAmount: moneyMatch(waterAmount), property, fileName, hasAttachment, message, receivedAt: new Date().toISOString() };
return recipients.map((recipient) => ({ json: { ...base, recipient }, binary: hasAttachment ? { invoiceFile: $binary[binaryKey] } : undefined }));

const original = $('Parse Invoice Email').item.json;
const mediaId = $json.id || $json.media_id || $json.mediaId;
if (!mediaId) throw new Error('Meta media upload did not return media id: ' + JSON.stringify($json));
return [{ json: { ...original, mediaId, body: { messaging_product: 'whatsapp', to: original.recipient, type: 'document', document: { id: mediaId, filename: original.fileName || 'invoice.pdf', caption: original.message } } } }];
